import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_kernel_code = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_op_kernel(
    const float* input,
    const float* multiplier,
    float negative_slope,
    float* output,
    int total_elements,
    int C,
    int H,
    int W) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_elements) return;

    int c = (idx / (H * W)) % C;
    float val = input[idx] * multiplier[c];

    // LeakyReLU
    val = val > 0 ? val : val * negative_slope;

    // GELU (exact version)
    const float sqrt2 = 1.41421356237f;
    float gelu = 0.5f * val * (1.0f + erff(val / sqrt2));

    output[idx] = gelu;
}

torch::Tensor fused_op_cuda(
    torch::Tensor input,
    torch::Tensor multiplier,
    float negative_slope) {

    auto output = torch::zeros_like(input);
    int total_elements = input.numel();
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    const int block_size = 256;
    int grid_size = (total_elements + block_size - 1) / block_size;

    fused_op_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        multiplier.data_ptr<float>(),
        negative_slope,
        output.data_ptr<float>(),
        total_elements,
        C,
        H,
        W
    );

    return output;
}
"""

fused_kernel_cpp = "torch::Tensor fused_op_cuda(torch::Tensor input, torch::Tensor multiplier, float negative_slope);"

fused_op = load_inline(
    name='fused_op',
    cpp_sources=fused_kernel_cpp,
    cuda_sources=fused_kernel_code,
    functions=['fused_op_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, multiplier_shape):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.multiplier = nn.Parameter(torch.randn(multiplier_shape))
        self.leaky_relu = nn.LeakyReLU()  # Maintain for negative_slope parameter

    def forward(self, x):
        x = self.conv(x)
        x = fused_op.fused_op_cuda(
            x, 
            self.multiplier.squeeze(),
            self.leaky_relu.negative_slope
        )
        return x
